/* Types */
/**
 *  Outcome of one「采集 / 同步」action, surfaced to the UI. Best-effort: every
 *  step runs independently, so `errors` carries per-step failures rather than
 *  aborting early. Empty on full success.
 */
export type AlignReport = {
	/**  Local collect outcome (zeroed if collect itself failed — see `errors`). */
	collected: IngestReport,
	/**  Rows imported from peer devices this round (Synced only). */
	imported: number,
	/**  True iff a local change was committed and pushed (Synced only). */
	pushed: boolean,
	/**  Per-step failures (`collect: …`, `pull: …`, `push: …`). Empty on success. */
	errors: string[],
};

/**
 *  The single error type crossing the Rust→JS boundary.
 * 
 *  Variants are kept coarse and serializable-friendly: low-level causes
 *  (io / rusqlite / git2) are stringified into `Internal` rather than leaked
 *  across the boundary, so the contract stays stable and specta-friendly.
 */
export type AppError = 
/**  The local data dir / config could not be created or read. */
{ type: "Config"; data: string } | 
/**  SQLite Local Store error. */
{ type: "Db"; data: string } | 
/**  A parser failed to discover/parse Source logs. */
{ type: "SourceParser"; data: string } | 
/**  Pricing lookup / cost calc error. */
{ type: "Pricing"; data: string } | 
/**  Sync (git2 / network) error — only raised in Synced mode. */
{ type: "Sync"; data: string } | 
/**
 *  模型列表获取失败（OpenAI 兼容 GET /v1/models，前端「获取模型列表」
 *  按钮）。串内带稳定前缀标签（AUTH_FAILED / ENDPOINT_CLOSED / TIMEOUT /
 *  BAD_FORMAT / NETWORK），前端按标签分桶成对应的 toast 提示——分桶
 *  契约见 `provider::model_fetch` 的模块文档。
 */
{ type: "FetchModels"; data: string } | 
/**  Catch-all for anything not covered above. */
{ type: "Internal"; data: string };

/**  Snapshot of app/status info for the UI on startup. */
export type AppInfo = {
	device_id: string,
	display_name: string,
	mode: RunMode,
	repo_url: string | null,
	masked_token: string | null,
	github_user: string | null,
	claude_projects_dir: string | null,
	version: string,
};

/**  Window-close behavior preference. Crosses the Rust→JS boundary. */
export type CloseBehavior = 
/**  Show the minimize/quit dialog each time (default). */
"ask" | 
/**  Always minimize to tray — keeps the background scheduler alive. */
"minimize" | 
/**  Always quit. */
"quit";

/**
 *  通用配置片段（全局一条，跨供应商共享）：手写 settings.json 片段 +
 *  勾选启用，切换写盘时合并进受控字段。存本机 config.json（不同步）；
 *  `content` 是片段 JSON 原文，编辑器直接编辑。
 */
export type CommonConfigSnippet = {
	/**  勾选「应用通用配置」启用；写盘时片段合并进受控字段。 */
	enabled: boolean,
	/**  片段 JSON 原文（原始文本；空串合法 = 无操作片段）。 */
	content: string,
};

/**  A known device. `is_self` marks the device running this instance. */
export type DeviceInfo = {
	device_id: string,
	display_name: string,
	is_self: boolean,
	first_seen: string,
};

/**
 *  File/folder counts for a device's library subtree, shown in the
 *  forget-device dialog so the user sees what they are migrating or deleting.
 *  f64 to stay specta-safe across the TS boundary (counts, never fractional).
 */
export type DeviceLibrarySummary = {
	files: number | null,
	dirs: number | null,
};

/**  Summary of one ingest run. */
export type IngestReport = {
	source: string,
	events_collected: number,
	rows_inserted: number,
	turn_durations_collected: number,
	turn_durations_inserted: number,
	files_scanned: number,
	lines_skipped: number,
};

/**
 *  Display language. Serialized lowercase (`en`/`zh`/`ja`), matching
 *  the frontend locale codes. The tray "Quit" item — the only user-facing Rust
 *  string — is localized from this; all other UI text is frontend i18n.
 */
export type Language = "en" | "zh" | "ja";

/**  One entry under a device's Library subtree, as shown in the list. */
export type LibraryEntry = {
	/**  Display name (file or dir basename). */
	name: string,
	kind: LibraryKind,
	/**  Bytes (files only; 0 for dirs — size is not recursed). */
	size: number | null,
	/**  Epoch millis (f64 — specta-safe, dayjs-friendly). */
	modified_ms: number | null,
	/**  Owning device id. */
	device_id: string,
	/**  Owning device display name (self name or a known alias). */
	device_name: string,
	is_self: boolean,
	/**
	 *  Path relative to the library root: `<deviceId>/<sub...>/<name>`. Used to
	 *  target delete / rename / export.
	 */
	rel_path: string,
	/**  Absolute filesystem path, for the frontend's `convertFileSrc` preview. */
	abs_path: string,
};

/**
 *  What `forget_device` does with a peer's library subtree
 *  (`repo/library/<peerId>/`).
 */
export type LibraryForgetAction = 
/**  Move the subtree into THIS device's library under `from-<peer>/`. */
"migrate" | 
/**  Delete the subtree outright. */
"delete";

/**  A Library entry is either a single file or a directory tree. */
export type LibraryKind = "file" | "dir";

/**
 *  How the lightweight glance card's tucked half-icon expands.
 *  Crosses the Rust→JS boundary; Rust itself doesn't act on it (a pure frontend
 *  interaction), but it rides `ConfigData` so every Settings preference lives in
 *  one place.
 */
export type LightweightExpand = 
/**  Click the half-icon to expand (default — won't fire on a stray hover). */
"click" | 
/**  Hover the half-icon to expand. */
"hover";

/**  A local group row (SQLite `local_groups`; device-private, never enters git). */
export type LocalGroup = {
	id: string,
	name: string,
	created_at: string,
	/**
	 *  Sort key within the track. `list_local_groups` orders by it (ties fall
	 *  back to name, keeping the pre-sort-order output deterministic).
	 */
	position: number,
};

/**  Query params for the request-log endpoint (adds paging to `UsageFilter`). */
export type LogsQuery = {
	filter: UsageFilter,
	limit: number,
	offset: number,
};

/**  Per-model aggregate row (for breakdown tables / model filter). */
export type ModelStatsRow = {
	model: string,
	request_count: number,
	total_tokens: number,
	total_cost_usd: number | null,
	/**
	 *  Cache-hit rate over this model's cacheable input pool, [0,1]
	 *  (`TokenCounts::cache_hit_rate`, computed at query time).
	 */
	cache_hit_rate: number | null,
};

/**  User-tunable preferences surfaced in the Settings「通用」card. */
export type Preferences = Preferences_Serialize | Preferences_Deserialize;

/**  User-tunable preferences surfaced in the Settings「通用」card. */
export type Preferences_Deserialize = {
	close_behavior: CloseBehavior,
	collect_interval_secs: number,
	push_interval_secs: number,
	language: Language,
	lightweight_expand: LightweightExpand,
	skin: Skin_Deserialize,
};

/**  User-tunable preferences surfaced in the Settings「通用」card. */
export type Preferences_Serialize = {
	close_behavior: CloseBehavior,
	collect_interval_secs: number,
	push_interval_secs: number,
	language: Language,
	lightweight_expand: LightweightExpand,
	skin: Skin_Serialize,
};

/**
 *  A pricing entry: USD per 1M tokens for each bucket.
 * 
 *  Cost crosses as `f64` for the UI; internally stored as Decimal TEXT.
 */
export type PricingEntry = {
	/**  Normalized model key (primary key). */
	model_key: string,
	display_name: string,
	/**  USD per 1M input tokens. */
	input_per_million: number | null,
	output_per_million: number | null,
	cache_read_per_million: number | null,
	cache_creation_per_million: number | null,
	/**  True when seeded from LiteLLM upstream, false when user-defined/edited. */
	is_builtin: boolean,
};

/**
 *  A provider (供应商): `settingsConfig` is a Claude Code `settings.json`
 *  snapshot (raw JSON text); `meta` carries app-side info the live file never
 *  sees. `sortIndex` is the user-ordered display rank.
 */
export type Provider = {
	id: string,
	name: string,
	websiteUrl: string,
	category: ProviderCategory,
	icon: string,
	iconColor: string,
	sortIndex: number,
	notes: string,
	/**  Claude Code `settings.json` snapshot, raw JSON text. */
	settingsConfig: string,
	/**  App-side extras, raw JSON text. Never written to the live file. */
	meta: string,
	updatedAt: string,
};

/**
 *  Provider category. `Custom` is the value for user-created providers; the
 *  rest label and theme the built-in presets in the list view.
 */
export type ProviderCategory = "official" | "cn_official" | "aggregator" | "cloud_provider" | "custom";

/**
 *  导入冲突模式：merge = 已有 id 跳过（保留双方，按 id 去重）；overwrite =
 *  同 id 以导入为准（后者胜），本地独有 id 保留（不做删除——保守迁移）。
 *  两种模式都不还原导出方的排序：已存在行保留本地 `sort_index`（排序是本地
 *  偏好，导入不做重排），导入的新行追加在末尾（`save_provider` 语义）。
 */
export type ProviderImportMode = "merge" | "overwrite";

/**
 *  导入结果计数，前端 toast 展示「导入 N 个、跳过 M 个」。用 `u32` 而非
 *  `usize`：本类型跨 Rust→JS 边界走 tauri-specta 的 typed 导出，specta 拒绝
 *  BigInt 型（`usize`/`u64`/`i64`…）字段以避免 JS 精度损失——用 `usize`
 *  会让 bindings.ts 生成失败。计数是行数（一次导入顶多几条），`u32` 足够。
 */
export type ProviderImportReport = {
	/**  实际写入的行数（merge = 新 id；overwrite = 全部导入行）。 */
	imported: number,
	/**  merge 模式下因 id 冲突被跳过的行数（overwrite 恒为 0）。 */
	skipped: number,
};

/**  Run mode: default Standalone; Synced once a repo is configured. */
export type RunMode = "standalone" | "synced";

/**
 *  Optional filter for `query_sessions`. Every field optional; `None` = no
 *  constraint. Mirrors the shape of `UsageFilter` for the session list.
 */
export type SessionFilter = {
	/**  Scope to one device (`None` = all devices). */
	device_scope: string | null,
	/**  Scope to one source, e.g. `claude_code`. */
	source: string | null,
	/**  `Some(true)` = only favorited; `Some(false)` = only non-favorited. */
	favorited: boolean | null,
	/**  Scope to a local group (empty string matches ungrouped). */
	local_group_id: string | null,
	/**  Scope to a synced group (empty string matches ungrouped). */
	synced_group_id: string | null,
	/**  Inclusive lower bound on `last_active_at` (ISO8601). */
	from_ts: string | null,
	/**  Inclusive upper bound on `last_active_at` (ISO8601). */
	to_ts: string | null,
	/**
	 *  Scope to sessions that have at least one usage record with this model
	 *  (EXISTS semantics — a session spanning several models matches any of
	 *  them). The model lives on `usage_records`, not on the session row.
	 */
	model: string | null,
};

/**
 *  One group entry for the frontend, unified across the two tracks. Order is
 *  carried by the ARRAY order `list_groups_dto` returns (already sorted by
 *  position per track) — no redundant per-row sort key.
 */
export type SessionGroup = {
	id: string,
	name: string,
	/**  `"local"` (device-private SQLite) or `"synced"` (per-device groups.json). */
	kind: string,
	/**  Owning device id. Only meaningful for `kind == "synced"`; empty for local. */
	device_id: string,
};

/**
 *  One transcript line. Single source of truth across three roles: parser
 *  output, the per-session JSONL Artifact (`sessions/<id>.jsonl`), and the DTO
 *  crossing to the frontend. The shape is identical for all three, so one
 *  struct (single source of truth) — a parser-emitted message is this same
 *  shape, not a separate type.
 */
export type SessionMessage = SessionMessage_Serialize | SessionMessage_Deserialize;

/**
 *  Role of a transcript line. Matches Claude Code's event types, collapsed to
 *  the four values the UI reasons about.
 */
export type SessionMessageRole = "user" | "assistant" | "tool" | "system";

/**
 *  One transcript line. Single source of truth across three roles: parser
 *  output, the per-session JSONL Artifact (`sessions/<id>.jsonl`), and the DTO
 *  crossing to the frontend. The shape is identical for all three, so one
 *  struct (single source of truth) — a parser-emitted message is this same
 *  shape, not a separate type.
 */
export type SessionMessage_Deserialize = {
	/**  Source event uuid (dedup key within one session's transcript file). */
	uuid: string,
	/**  Session this message belongs to. */
	session_id: string,
	role: SessionMessageRole,
	/**  ISO8601 timestamp of the source event. */
	ts: string,
	/**  Model on assistant messages (None for user/tool/system). */
	model?: string | null,
	/**  Tool name on tool_use messages (None otherwise). */
	name?: string | null,
	/**
	 *  Trimmed text content: text blocks for user/assistant, the tool_use `name`
	 *  summary for tool calls; thinking blocks' full text, base64 images, and
	 *  >32 KB tool_results are filtered/truncated at collect time.
	 */
	content: string,
};

/**
 *  One transcript line. Single source of truth across three roles: parser
 *  output, the per-session JSONL Artifact (`sessions/<id>.jsonl`), and the DTO
 *  crossing to the frontend. The shape is identical for all three, so one
 *  struct (single source of truth) — a parser-emitted message is this same
 *  shape, not a separate type.
 */
export type SessionMessage_Serialize = {
	/**  Source event uuid (dedup key within one session's transcript file). */
	uuid: string,
	/**  Session this message belongs to. */
	session_id: string,
	role: SessionMessageRole,
	/**  ISO8601 timestamp of the source event. */
	ts: string,
	/**  Model on assistant messages (None for user/tool/system). */
	model?: string | null,
	/**  Tool name on tool_use messages (None otherwise). */
	name?: string | null,
	/**
	 *  Trimmed text content: text blocks for user/assistant, the tool_use `name`
	 *  summary for tool calls; thinking blocks' full text, base64 images, and
	 *  >32 KB tool_results are filtered/truncated at collect time.
	 */
	content: string,
};

/**
 *  One session row for the frontend list. Aggregates (request_count /
 *  total_tokens / total_cost_usd) are computed live by `GROUP BY session_id`
 *  over `usage_records` at query time — they are NOT stored on the session, so
 *  there is no second source of token/cost truth to drift.
 */
export type SessionRow = {
	id: string,
	device_id: string,
	source: string,
	project_dir: string,
	/**  Display title: `custom_title` when set, else `title_orig`. */
	title: string,
	/**  `""` = main session; non-empty = subagent type tag (e.g. `Explore`). */
	agent_type: string,
	favorited: boolean,
	local_group_id: string,
	synced_group_id: string,
	started_at: string,
	last_active_at: string,
	/**  Live aggregate over `usage_records` for this session. */
	request_count: number,
	/**  Live aggregate: sum of all four token buckets. */
	total_tokens: number,
	/**  Live aggregate: sum of cost. */
	total_cost_usd: number | null,
};

/**
 *  Color skin for multi-skin theming (token-first). Serialized
 *  snake_case; `neutral` is the default and maps to NO `data-skin` attribute on
 *  `<html>` (the :root/.dark values in src/index.css ARE the Neutral palette —
 *  pure greyscale chrome over a default multi-hue chart). Per-device, not synced
 *  (config.json never enters the repo). The four chromatic skins each override
 *  `--brand` (+ `--brand-strong`) and the button-foreground vars in index.css;
 *  everything else holds. The frontend applies it; Rust only stores it.
 * 
 *  Back-compat: the legacy snake_case names (`pixso`/`cuiwei`/`tingwu`/
 *  `yanzhi`/`zizi`) are accepted as aliases, so an older config.json lands on
 *  the closest new skin instead of failing to deserialize — `pixso` (the old
 *  default) → `Neutral` (the new default); the rest map by hue family.
 */
export type Skin = Skin_Serialize | Skin_Deserialize;

/**
 *  Color skin for multi-skin theming (token-first). Serialized
 *  snake_case; `neutral` is the default and maps to NO `data-skin` attribute on
 *  `<html>` (the :root/.dark values in src/index.css ARE the Neutral palette —
 *  pure greyscale chrome over a default multi-hue chart). Per-device, not synced
 *  (config.json never enters the repo). The four chromatic skins each override
 *  `--brand` (+ `--brand-strong`) and the button-foreground vars in index.css;
 *  everything else holds. The frontend applies it; Rust only stores it.
 * 
 *  Back-compat: the legacy snake_case names (`pixso`/`cuiwei`/`tingwu`/
 *  `yanzhi`/`zizi`) are accepted as aliases, so an older config.json lands on
 *  the closest new skin instead of failing to deserialize — `pixso` (the old
 *  default) → `Neutral` (the new default); the rest map by hue family.
 */
export type Skin_Deserialize = "neutral" | "pixso" | "sage" | "cuiwei" | "azure" | "tingwu" | "crimson" | "yanzhi" | "mauve" | "zizi";

/**
 *  Color skin for multi-skin theming (token-first). Serialized
 *  snake_case; `neutral` is the default and maps to NO `data-skin` attribute on
 *  `<html>` (the :root/.dark values in src/index.css ARE the Neutral palette —
 *  pure greyscale chrome over a default multi-hue chart). Per-device, not synced
 *  (config.json never enters the repo). The four chromatic skins each override
 *  `--brand` (+ `--brand-strong`) and the button-foreground vars in index.css;
 *  everything else holds. The frontend applies it; Rust only stores it.
 * 
 *  Back-compat: the legacy snake_case names (`pixso`/`cuiwei`/`tingwu`/
 *  `yanzhi`/`zizi`) are accepted as aliases, so an older config.json lands on
 *  the closest new skin instead of failing to deserialize — `pixso` (the old
 *  default) → `Neutral` (the new default); the rest map by hue family.
 */
export type Skin_Serialize = "neutral" | "sage" | "azure" | "crimson" | "mauve";

/**  A synced-group row (`data/<deviceId>/groups.json`; cross-device via git). */
export type SyncedGroup = {
	id: string,
	name: string,
	/**
	 *  Owning device (the one that created the group). Encoded in the id prefix
	 *  too, but kept here for read-without-parse convenience.
	 */
	device_id: string,
	updated_at: string,
	/**
	 *  User-ordered position WITHIN this device's own groups (array index order
	 *  can't survive the per-device merge, so the rank is explicit data). Old
	 *  files lack the field — `default_group_position` (MAX) sorts them last.
	 */
	position?: number,
};

/**  Token four-pack (per-call). `u32` across the boundary. */
export type TokenCounts = {
	input: number,
	output: number,
	cache_creation: number,
	cache_read: number,
};

/**
 *  Trend aggregation granularity. `Day` groups on the UTC `day` column
 *  (cross-device deterministic); `Hour` groups on local-time hour,
 *  used for the single-day zoom where per-day resolution collapses to one bar.
 */
export type TrendBucket = "Day" | "Hour";

/**
 *  One point on the trend chart. `day` carries the bucket key: a `YYYY-MM-DD`
 *  UTC day (`TrendBucket::Day`) or a `YYYY-MM-DDTHH` local hour
 *  (`TrendBucket::Hour`). The field keeps the `day` name for wire stability.
 */
export type TrendPoint = {
	day: string,
	total_tokens: number,
	input_tokens: number,
	output_tokens: number,
	cache_creation_tokens: number,
	cache_read_tokens: number,
	total_cost_usd: number | null,
};

/**  One item the user is uploading (from the pending-upload dialog). */
export type UploadItem = {
	/**  Absolute source path on this machine (from the drag-drop event). */
	source_path: string,
	/**  Final name in the library (the user may have renamed it). */
	target_name: string,
};

/**
 *  Filter args shared by stats / trend / logs queries.
 * 
 *  All fields optional; `None` means "no constraint". `device_scope` is the
 *  semantic cache-key axis: `None` = all devices.
 * 
 *  Range bounds are ISO8601 **timestamps**, not `day` strings. The `day` column
 *  is a UTC whole-day bucket (cross-device determinism), so a local
 *  "today" in a non-UTC zone (e.g. UTC+8) straddles two UTC days; filtering on
 *  `day` would drop early-morning rows. The frontend converts its local-day
 *  range to UTC timestamps, and we filter on `timestamp` (amendment:
 *  `day` stays the UTC bucket for grouping/trend only).
 */
export type UsageFilter = {
	/**  Inclusive lower ISO8601 UTC timestamp, e.g. `2026-07-21T16:00:00Z`. */
	from_ts: string | null,
	/**  Inclusive upper ISO8601 UTC timestamp. */
	to_ts: string | null,
	model: string | null,
	source: string | null,
	device_scope: string | null,
};

/**  One row of the request-log table. */
export type UsageLogRow = {
	uuid: string,
	timestamp: string,
	model: string,
	source: string,
	device_id: string,
	tokens: TokenCounts,
	stop_reason: string,
	total_cost_usd: number | null,
};

/**  Aggregate totals over a filtered range. */
export type UsageStats = {
	request_count: number,
	total_tokens: number,
	input_tokens: number,
	output_tokens: number,
	cache_creation_tokens: number,
	cache_read_tokens: number,
	/**  Cache-hit ratio in [0,1]. */
	cache_hit_rate: number | null,
	total_cost_usd: number | null,
	/**  Aggregate over TurnDuration rows in range (per-turn grain). */
	turn_count: number,
	avg_turn_duration_ms: number | null,
};

/**
 *  Outcome of a remote probe, surfaced to the UI. Always returned as `Ok`: a
 *  failed probe is a business result (`ok: false`), not an `AppError`, so the
 *  frontend reads `report.ok` instead of catching an exception.
 */
export type VerifyReport = {
	/**
	 *  True iff the repo was reachable, the PAT authenticated, and the caller
	 *  has read access.
	 */
	ok: boolean,
	/**  Human-readable status (zh), shown verbatim in the Settings banner. */
	message: string,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

